const capacitySteps = `-- name: CapacitySteps :many
SELECT step, started_at, ended_at, outcome, calls, joined, pending, failed, late, join_seconds,
    answer_seconds, no_answer, tester_cpu_percent
FROM capacity_steps WHERE run_id = $1 ORDER BY step
`

type CapacityStepsRow struct {
	Step             int32
	StartedAt        pgtype.Timestamptz
	EndedAt          pgtype.Timestamptz
	Outcome          string
	Calls            int32
	Joined           int32
	Pending          int32
	Failed           int32
	Late             int32
	JoinSeconds      []float64
	AnswerSeconds    []float64
	NoAnswer         int32
	TesterCpuPercent pgtype.Float8
}

func (q *Queries) CapacitySteps(ctx context.Context, runID pgtype.UUID) ([]CapacityStepsRow, error) {
	rows, err := q.db.Query(ctx, capacitySteps, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CapacityStepsRow
	for rows.Next() {
		var i CapacityStepsRow
		if err := rows.Scan(
			&i.Step,
			&i.StartedAt,
			&i.EndedAt,
			&i.Outcome,
			&i.Calls,
			&i.Joined,
			&i.Pending,
			&i.Failed,
			&i.Late,
			&i.JoinSeconds,
			&i.AnswerSeconds,
			&i.NoAnswer,
			&i.TesterCpuPercent,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const claimAlertDeliveries = `-- name: ClaimAlertDeliveries :many
UPDATE alert_deliveries d SET lease_until = $1
WHERE d.id IN (
    SELECT x.id FROM alert_deliveries x
    WHERE x.state IN ('pending', 'retrying') AND x.next_attempt_at <= $2
      AND (x.lease_until IS NULL OR x.lease_until < $2)
    ORDER BY x.next_attempt_at
    LIMIT $3
    FOR UPDATE SKIP LOCKED)
RETURNING d.id, d.organisation_id, d.project_id, d.incident_id, d.channel, d.change, d.idempotency_key, d.message, d.attempts, d.created_at
`

type ClaimAlertDeliveriesParams struct {
	LeaseUntil pgtype.Timestamptz
	Now        pgtype.Timestamptz
	MaxRows    int32
}

type ClaimAlertDeliveriesRow struct {
	ID             pgtype.UUID
	OrganisationID string
	ProjectID      string
	IncidentID     pgtype.UUID
	Channel        string
	Change         string
	IdempotencyKey string
	Message        []byte
	Attempts       int32
	CreatedAt      pgtype.Timestamptz
}

// Due deliveries, leased so a second worker skips them; a lease that lapses (a crashed worker) frees
// the delivery for the next claim.
func (q *Queries) ClaimAlertDeliveries(ctx context.Context, arg ClaimAlertDeliveriesParams) ([]ClaimAlertDeliveriesRow, error) {
	rows, err := q.db.Query(ctx, claimAlertDeliveries, arg.LeaseUntil, arg.Now, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ClaimAlertDeliveriesRow
	for rows.Next() {
		var i ClaimAlertDeliveriesRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganisationID,
			&i.ProjectID,
			&i.IncidentID,
			&i.Channel,
			&i.Change,
			&i.IdempotencyKey,
			&i.Message,
			&i.Attempts,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

